7	import type { Content } from '@google/genai';
8	import type { ConcreteNode } from './types.js';
9	import type { ContextTracer } from '../tracer.js';
10	import type { ContextProfile } from '../config/profiles.js';
11	import type { PipelineOrchestrator } from '../pipeline/orchestrator.js';
12	import type { ContextEnvironment } from '../pipeline/environment.js';
13	
14	/**
15	 * Maps the Episodic Context Graph back into a raw Gemini Content[] array for transmission.
16	 * It applies synchronous context management (GC backstop) if the budget is exceeded.
17	 */
18	export async function render(
19	  nodes: readonly ConcreteNode[],
20	  orchestrator: PipelineOrchestrator,
21	  sidecar: ContextProfile,
22	  tracer: ContextTracer,
23	  env: ContextEnvironment,
24	  protectionReasons: Map<string, string> = new Map(),
25	  headerTokens: number = 0,
26	): Promise<{ history: Content[]; didApplyManagement: boolean }> {
27	  if (!sidecar.config.budget) {
28	    const contents = env.graphMapper.fromGraph(nodes);
29	    tracer.logEvent('Render', 'Render Context to LLM (No Budget)', {
30	      renderedContext: contents,
31	    });
32	    return { history: contents, didApplyManagement: false };
33	  }
34	
35	  const maxTokens = sidecar.config.budget.maxTokens;
36	  const graphTokens = env.tokenCalculator.calculateConcreteListTokens(nodes);
37	  const currentTokens = graphTokens + headerTokens;
38	
39	  const protectedIds = new Set(protectionReasons.keys());
40	
41	  tracer.logEvent('Render', 'Budget Audit', {
42	    maxTokens,
43	    retainedTokens: sidecar.config.budget.retainedTokens,
44	    graphTokens,
45	    headerTokens,
46	    currentTokens,
47	    pressure: (currentTokens / maxTokens).toFixed(2),
48	    isOverBudget: currentTokens > maxTokens,
49	  });
50	
51	  tracer.logEvent('Render', 'Estimation Calibration', {
52	    breakdown: env.tokenCalculator.calculateTokenBreakdown(nodes),
53	  });
54	
55	  tracer.logEvent('Render', 'Protection Audit', {
56	    reasons: Object.fromEntries(protectionReasons),
57	  });
58	
59	  if (currentTokens <= maxTokens) {
60	    tracer.logEvent(
61	      'Render',
62	      `View is within maxTokens (${currentTokens} <= ${maxTokens}). Returning view.`,
63	    );
64	    const contents = env.graphMapper.fromGraph(nodes);
65	    tracer.logEvent('Render', 'Render Context for LLM', {
66	      renderedContext: contents,
67	    });
68	    return { history: contents, didApplyManagement: false };
69	  }
70	
71	  const targetDelta = currentTokens - sidecar.config.budget.retainedTokens;
72	  tracer.logEvent(
73	    'Render',
74	    `View exceeds maxTokens (${currentTokens} > ${maxTokens}). Hitting Synchronous Pressure Barrier.`,
75	    { targetDelta },
76	  );
77	
78	  // Calculate exactly which nodes aged out of the retainedTokens budget to form our target delta
79	  const agedOutNodes = new Set<string>();
80	  let rollingTokens = 0;
81	  // Start from newest and count backwards
82	  for (let i = nodes.length - 1; i >= 0; i--) {
83	    const node = nodes[i];
84	    const nodeTokens = env.tokenCalculator.calculateConcreteListTokens([node]);
85	    rollingTokens += nodeTokens;
86	    if (rollingTokens > sidecar.config.budget.retainedTokens) {
87	      agedOutNodes.add(node.id);
88	    }
89	  }
90	
91	  const processedNodes = await orchestrator.executeTriggerSync(
92	    'gc_backstop',
93	    nodes,
94	    agedOutNodes,
95	    protectedIds,
96	  );
97	
98	  // Apply skipList logic to abstract over summarized nodes
99	  const skipList = new Set<string>();
100	  for (const node of processedNodes) {
101	    if (node.abstractsIds) {
102	      for (const id of node.abstractsIds) skipList.add(id);
103	    }
104	  }
105	
106	  const visibleNodes = processedNodes.filter((n) => !skipList.has(n.id));
107	
108	  const contents = env.graphMapper.fromGraph(visibleNodes);
109	  tracer.logEvent('Render', 'Render Sanitized Context for LLM', {
110	    renderedContextSanitized: contents,
111	  });
112	  return { history: contents, didApplyManagement: true };
113	}
