7	import type { Content, Part } from '@google/genai';
8	import { type ConcreteNode, NodeType } from './types.js';
9	import { randomUUID, createHash } from 'node:crypto';
10	import { debugLogger } from '../../utils/debugLogger.js';
11	
12	interface PartWithSynthId extends Part {
13	  _synthId?: string;
14	}
15	
16	// Global WeakMap to cache hashes for Part objects.
17	// This optimizes getStableId by avoiding redundant stringify/hash operations
18	// on the same object instances across multiple management passes.
19	const PART_HASH_CACHE = new WeakMap<object, string>();
20	
21	function isTextPart(part: Part): part is Part & { text: string } {
22	  return typeof part.text === 'string';
23	}
24	
25	function isInlineDataPart(
26	  part: Part,
27	): part is Part & { inlineData: { data: string } } {
28	  return (
29	    typeof part.inlineData === 'object' &&
30	    part.inlineData !== null &&
31	    typeof part.inlineData.data === 'string'
32	  );
33	}
34	
35	function isFileDataPart(
36	  part: Part,
37	): part is Part & { fileData: { fileUri: string } } {
38	  return (
39	    typeof part.fileData === 'object' &&
40	    part.fileData !== null &&
41	    typeof part.fileData.fileUri === 'string'
42	  );
43	}
44	
45	function isFunctionCallPart(
46	  part: Part,
47	): part is Part & { functionCall: { id: string; name: string } } {
48	  return (
49	    typeof part.functionCall === 'object' &&
50	    part.functionCall !== null &&
51	    typeof part.functionCall.name === 'string'
52	  );
53	}
54	
55	function isFunctionResponsePart(
56	  part: Part,
57	): part is Part & { functionResponse: { id: string; name: string } } {
58	  return (
59	    typeof part.functionResponse === 'object' &&
60	    part.functionResponse !== null &&
61	    typeof part.functionResponse.name === 'string'
62	  );
63	}
64	
65	/**
66	 * Generates a stable ID for an object reference using a WeakMap.
67	 * Falls back to content-based hashing for Part-like objects to ensure
68	 * stability across object re-creations (e.g. during history mapping).
69	 */
70	export function getStableId(
71	  obj: object,
72	  nodeIdentityMap: WeakMap<object, string>,
73	  turnSalt: string = '',
74	  partIdx: number = 0,
75	): string {
76	  let id = nodeIdentityMap.get(obj);
77	  if (id) return id;
78	
79	  const cachedHash = PART_HASH_CACHE.get(obj);
80	  if (cachedHash) {
81	    id = `${cachedHash}_${turnSalt}_${partIdx}`;
82	    nodeIdentityMap.set(obj, id);
83	    return id;
84	  }
85	
86	  const part = obj as PartWithSynthId;
87	  let contentHash: string | undefined;
88	
89	  // If the object already has a synthetic ID property, use it.
90	  if (typeof part._synthId === 'string') {
91	    id = part._synthId;
92	  } else if (isTextPart(part)) {
93	    contentHash = createHash('sha256').update(part.text).digest('hex');
94	    id = `text_${contentHash}_${turnSalt}_${partIdx}`;
95	  } else if (isInlineDataPart(part)) {
96	    contentHash = createHash('sha256')
97	      .update(part.inlineData.data)
98	      .digest('hex');
99	    id = `media_${contentHash}_${turnSalt}_${partIdx}`;
100	  } else if (isFileDataPart(part)) {
101	    contentHash = createHash('sha256')
102	      .update(part.fileData.fileUri)
103	      .digest('hex');
104	    id = `file_${contentHash}_${turnSalt}_${partIdx}`;
105	  } else if (isFunctionCallPart(part)) {
106	    contentHash = createHash('sha256')
107	      .update(
108	        `call:${part.functionCall.name}:${JSON.stringify(part.functionCall.args)}`,
109	      )
110	      .digest('hex');
111	    id = `call_h_${contentHash}_${turnSalt}_${partIdx}`;
112	  } else if (isFunctionResponsePart(part)) {
113	    contentHash = createHash('sha256')
114	      .update(
115	        `resp:${part.functionResponse.name}:${JSON.stringify(part.functionResponse.response)}`,
116	      )
117	      .digest('hex');
118	    id = `resp_h_${contentHash}_${turnSalt}_${partIdx}`;
119	  }
120	
121	  if (contentHash) {
122	    PART_HASH_CACHE.set(obj, contentHash);
123	  }
124	
125	  if (!id) {
126	    id = randomUUID();
127	  }
128	
129	  nodeIdentityMap.set(obj, id);
130	  return id;
131	}
