15	/**
16	 * Connects the raw AgentChatHistory to the ContextManager.
17	 * It maps raw messages into Episodic Intermediate Representation (Context Graph)
18	 * and evaluates background triggers whenever history changes.
19	 */
20	export class HistoryObserver {
21	  private unsubscribeHistory?: () => void;
22	
23	  private readonly seenNodeIds = new Set<string>();
24	
25	  constructor(
26	    private readonly chatHistory: AgentChatHistory,
27	    private readonly eventBus: ContextEventBus,
28	    private readonly tracer: ContextTracer,
29	    private readonly graphMapper: ContextGraphMapper,
30	  ) {}
31	
32	  private processEvent = (event: HistoryEvent) => {
33	    if (event.type === 'CLEAR') {
34	      this.seenNodeIds.clear();
35	    }
36	
37	    if (event.type === 'SILENT_SYNC') {
38	      return;
39	    }
40	
41	    // Always process the FULL history to provide a complete view to the ContextManager.
42	    // The ContextManager relies on the 'nodes' array to be the TOTAL set of valid pristine nodes.
43	    const fullHistory = this.chatHistory.get();
44	    const nodes = this.graphMapper.applyEvent({
45	      ...event,
46	      payload: fullHistory,
47	    });
48	
49	    const newNodes = new Set<string>();
50	    for (const node of nodes) {
51	      if (!this.seenNodeIds.has(node.id)) {
52	        newNodes.add(node.id);
53	        this.seenNodeIds.add(node.id);
54	      }
55	    }
56	
57	    this.tracer.logEvent(
58	      'HistoryObserver',
59	      `Rebuilt pristine graph from ${event.type} event`,
60	      { nodesSize: nodes.length, newNodesCount: newNodes.size },
61	    );
62	
63	    this.eventBus.emitPristineHistoryUpdated({
64	      nodes,
65	      newNodes,
66	    });
67	  };
68	
69	  start() {
70	    if (this.unsubscribeHistory) {
71	      this.unsubscribeHistory();
72	    }
73	
74	    this.unsubscribeHistory = this.chatHistory.subscribe(this.processEvent);
75	
76	    // Process any existing history immediately upon start
77	    const existing = this.chatHistory.get();
78	    if (existing && existing.length > 0) {
79	      this.processEvent({ type: 'SYNC_FULL', payload: existing });
80	    }
81	  }
82	
83	  stop() {
84	    if (this.unsubscribeHistory) {
85	      this.unsubscribeHistory();
86	      this.unsubscribeHistory = undefined;
87	    }
88	  }
89	}
